mapper.select:
SELECT id FROM public.department_admin_invitation_outbox
WHERE status IN ('PENDING', 'RETRY') AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, id LIMIT #{limit}

mapper.update:
UPDATE public.department_admin_invitation_outbox
SET status = 'SENT', sent_at = #{sentAt}, lease_until = NULL,
    last_error_code = NULL, updated_at = #{sentAt}
WHERE id = #{id} AND status = 'PROCESSING' AND claim_version = #{claimVersion}

UPDATE public.department_admin_invitation_outbox
SET status = 'RETRY', next_attempt_at = #{nextAttemptAt}, lease_until = NULL,
    last_error_code = #{errorCode}, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING' AND claim_version = #{claimVersion}

UPDATE public.department_admin_invitation_outbox
SET status = 'DEAD', lease_until = NULL, last_error_code = #{errorCode}, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING' AND claim_version = #{claimVersion}

UPDATE public.department_admin_invitation_outbox
SET status = 'CANCELED', lease_until = NULL, last_error_code = NULL, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING' AND claim_version = #{claimVersion}

UPDATE public.department_admin_invitation_outbox
SET status = 'RETRY', next_attempt_at = #{now}, lease_until = NULL,
    last_error_code = 'MAIL_LEASE_EXPIRED', updated_at = #{now}
WHERE status = 'PROCESSING' AND lease_until <= #{now}
